mapper.select:
SELECT i.PROJ_ID AS "projectId", FROM TB_PJ_ISSUE i
WHERE i.PROJ_ID IN #{id}
ORDER BY i.PROJ_ID,i.ISSUE_ID

sql.if:
AND (FALSE
OR ${proj} IN #{scopeProject}
OR EXISTS (SELECT 1 FROM TB_PJ_PROJ_PART scope_part WHERE scope_part.PROJ_ID=${proj}
  AND scope_part.APLY_BGN_YM=COALESCE((SELECT max(scope_x.APLY_BGN_YM) FROM TB_PJ_PROJ_PART scope_x WHERE scope_x.PROJ_ID=${proj}
      AND scope_x.APLY_BGN_YM <= to_char(clock_timestamp() AT TIME ZONE 'Asia/Seoul','YYYYMM')),
    (SELECT min(scope_x.APLY_BGN_YM) FROM TB_PJ_PROJ_PART scope_x WHERE scope_x.PROJ_ID=${proj}))
  AND scope_part.PART_ID IN #{scopePart}))
